/**
 * The contract with the Rust side (docs/rust-sdk-design.md §7): golden
 * vectors generated by tvpipe's own tests, read from the repository.
 *
 * - machine/events.txt: every event type tvpipe writes parses, and the set
 *   of types is EVENT_TYPES (which the TvpipeEvent union must match).
 * - slrw/records.txt: this SDK's SLRW encoder makes the same bytes.
 * - machine/sessions/*.txt: recorded sessions, replayed through a stub
 *   binary, end the way they ended for tvpipe.
 */

import assert from "node:assert/strict";
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { test } from "node:test";

import { EVENT_TYPES, parseEvent } from "../src/events.ts";
import { play, stream, testPattern, TvpipeError, type Session } from "../src/index.ts";
import * as slrw from "../src/slrw.ts";
import { repo, stubBinary } from "./helpers.ts";

const vectors = join(repo, "crates", "tvpipe", "tests", "vectors");
const unix = process.platform !== "win32";

/** The `key = value` blocks of a vector file. */
function blocks(file: string): Map<string, string>[] {
  const out: Map<string, string>[] = [];
  let cur = new Map<string, string>();
  for (const line of readFileSync(file, "utf8").split("\n")) {
    if (line.trim() === "") {
      if (cur.size) out.push(cur);
      cur = new Map();
      continue;
    }
    if (line.startsWith("#")) continue;
    const i = line.indexOf("=");
    if (i < 0) continue;
    cur.set(line.slice(0, i).trim(), line.slice(i + 1).trim());
  }
  if (cur.size) out.push(cur);
  return out;
}

const hex = (s: string) => Uint8Array.from(Buffer.from(s, "hex"));

test("every event in the golden vectors parses, and the types match", () => {
  const seen = new Set<string>();
  for (const b of blocks(join(vectors, "machine", "events.txt"))) {
    const ev = parseEvent(b.get("json")!);
    assert.ok(ev, b.get("name"));
    assert.equal(ev.type, b.get("type"), b.get("name"));
    seen.add(ev.type);
  }
  assert.deepEqual([...seen].sort(), [...EVENT_TYPES].sort());
});

test("SLRW records have tvpipe's bytes", () => {
  for (const b of blocks(join(vectors, "slrw", "records.txt"))) {
    const name = b.get("name")!;
    const want = [...hex(b.get("bytes")!)];
    let have: Uint8Array;
    if (name === "magic") have = slrw.MAGIC;
    else if (b.has("flags")) have = slrw.control(Number(b.get("flags")));
    else if (b.has("command")) have = slrw.command(JSON.parse(b.get("command")!));
    else if (b.has("f32")) {
      const f = new Float32Array(b.get("f32")!.split(" ").map(Number));
      have = slrw.record(Number(b.get("kind")) as slrw.KindCode, 0, slrw.floatToS16(f));
    } else {
      const prefix = b.has("prefix") ? Number(b.get("prefix")) : undefined;
      have = slrw.record(
        Number(b.get("kind")) as slrw.KindCode,
        BigInt(b.get("pts_us")!),
        hex(b.get("payload") ?? ""),
        prefix,
      );
    }
    assert.deepEqual([...have], want, name);
  }
});

/** A stub that replays a recorded session's events, then exits. */
function replay(file: string): { binary: string; exit: number; outcome: string; args: string[] } {
  const text = readFileSync(file, "utf8");
  const meta = (k: string) => text.match(new RegExp(`^# ${k}: (.*)$`, "m"))?.[1] ?? "";
  // The stub writes its own hello.
  const lines = text.split("\n").filter((l) => l.startsWith("{") && !l.includes('"type":"hello"'));
  const exit = Number(meta("exit"));
  const { binary } = stubBinary(`
    for (const l of ${JSON.stringify(lines)}) process.stdout.write(l + "\\n");
    finish(${exit});
  `);
  return { binary, exit, outcome: meta("outcome"), args: meta("args").split(" ") };
}

for (const f of readdirSync(join(vectors, "machine", "sessions"))) {
  test(`replayed session ${f}`, { skip: !unix }, async () => {
    const r = replay(join(vectors, "machine", "sessions", f));
    const [kind, detail] = r.outcome.split(" ");
    const start = (): Promise<Session> => {
      if (r.args.join(" ").startsWith("debug pattern")) return testPattern({ binary: r.binary, to: "browser" });
      if (r.args.at(-1) === "-") {
        return stream({ binary: r.binary, to: "browser", video: { width: 64, height: 48, fps: 30 } });
      }
      return play(r.args.at(-1)!, { binary: r.binary, to: "browser" });
    };
    if (kind === "error") {
      await assert.rejects(start(), (e: unknown) => e instanceof TvpipeError && e.code === detail);
      return;
    }
    const s = await start();
    const end = await s.done;
    assert.equal(end.reason, detail);
    assert.equal(end.exitCode, r.exit);
  });
}
